 734→/// Sync shared config files for a workspace.
 735→fn cmd_sync(workspace_arg: Option<String>) -> i32 {
 736→    let st = match state::load() {
 737→        Ok(s) => s,
 738→        Err(e) => {
 739→            error!("{e}");
 740→            return 1;
 741→        }
 742→    };
 743→
 744→    // Resolve which workspace we're syncing
 745→    let entry = if let Some(ws) = workspace_arg {
 746→        match st.resolve_workspace(&ws) {
 747→            Some(e) => e.clone(),
 748→            None => {
 749→                error!("unknown workspace '{ws}'");
 750→                return 1;
 751→            }
 752→        }
 753→    } else {
 754→        match detect_workspace(&st) {
 755→            Some(e) => e,
 756→            None => {
 757→                error!("not inside a dual workspace");
 758→                info!("Usage: dual sync [workspace]");
 759→                return 1;
 760→            }
 761→        }
 762→    };
 763→
 764→    // Load hints
 765→    let workspace_dir = st.workspace_dir(&entry);
 766→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
 767→    let shared_config = match &hints.shared {
 768→        Some(s) if !s.files.is_empty() => s,
 769→        _ => {
 770→            error!("no [shared] section in .dual.toml (or files list is empty)");
 771→            return 1;
 772→        }
 773→    };
 774→
 775→    let shared_dir = match shared::ensure_shared_dir(&entry.repo) {
 776→        Ok(d) => d,
 777→        Err(e) => {
 778→            error!("{e}");
 779→            return 1;
 780→        }
 781→    };
 782→
 783→    let is_main = entry.path.is_some();
 784→
 785→    if is_main {
 786→        // Main workspace: init shared dir, then prompt to sync all branches
 787→        match shared::init_from_main(&workspace_dir, &shared_dir, &shared_config.files) {
 788→            Ok(moved) => {
 789→                for f in &moved {
 790→                    info!("  moved {f} → shared/");
 791→                }
 792→            }
 793→            Err(e) => {
 794→                error!("{e}");
 795→                return 1;
 796→            }
 797→        }
 798→
 799→        // Prompt to sync all branches
 800→        let branches: Vec<_> = st
 801→            .workspaces_for_repo(&entry.repo)
 802→            .into_iter()
 803→            .filter(|ws| ws.path.is_none())
 804→            .collect();
 805→
 806→        if branches.is_empty() {
 807→            info!("No branch workspaces to sync.");
 808→            return 0;
 809→        }
 810→
 811→        // Interactive prompt — use println! directly since this is user interaction
 812→        println!(
 813→            "\nSync shared files to ALL {} branch workspace(s)? [y/N]",
 814→            branches.len()
 815→        );
 816→        let mut input = String::new();
 817→        std::io::stdin().read_line(&mut input).unwrap_or(0);
 818→        if !input.trim().eq_ignore_ascii_case("y") {
 819→            info!("Cancelled.");
 820→            return 0;
 821→        }
 822→
 823→        for branch_entry in &branches {
 824→            let branch_dir = st.workspace_dir(branch_entry);
 825→            if !branch_dir.exists() {
 826→                continue; // Not yet cloned
 827→            }
 828→            let ws_id = config::workspace_id(&branch_entry.repo, &branch_entry.branch);
 829→            match shared::copy_to_branch(&branch_dir, &shared_dir, &shared_config.files) {
 830→                Ok(copied) => {
 831→                    info!("{ws_id}: synced {} file(s)", copied.len());
 832→                }
 833→                Err(e) => error!("{ws_id}: {e}"),
 834→            }
 835→        }
 836→    } else {
 837→        // Branch workspace: copy from shared dir
 838→        match shared::copy_to_branch(&workspace_dir, &shared_dir, &shared_config.files) {
 839→            Ok(copied) => {
 840→                if copied.is_empty() {
 841→                    info!(
 842→                        "No shared files available yet. Run `dual sync` in the main workspace first."
 843→                    );
 844→                } else {
 845→                    for f in &copied {
 846→                        info!("  synced {f}");
 847→                    }
 848→                }
 849→            }
 850→            Err(e) => {
 851→                error!("{e}");
 852→                return 1;
 853→            }
 854→        }
 855→    }
 856→
 857→    0
 858→}
