 860→/// Detect the repo name from the current working directory.
 861→///
 862→/// Matches the git remote URL of the cwd against known workspace URLs in state.
 863→fn detect_repo_from_cwd(st: &state::WorkspaceState) -> Option<String> {
 864→    let (_, url, _) = detect_git_repo().ok()?;
 865→
 866→    // Match against known workspace URLs
 867→    for ws in st.all_workspaces() {
 868→        if ws.url == url {
 869→            return Some(ws.repo.clone());
 870→        }
 871→    }
 872→
 873→    // Also try matching by git root path against workspace paths
 874→    let cwd = std::env::current_dir().ok()?;
 875→    let root = std::process::Command::new("git")
 876→        .args(["rev-parse", "--show-toplevel"])
 877→        .output()
 878→        .ok()
 879→        .filter(|o| o.status.success())
 880→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))?;
 881→
 882→    for ws in st.all_workspaces() {
 883→        let ws_dir = st.workspace_dir(ws);
 884→        if ws_dir == root || ws_dir == cwd {
 885→            return Some(ws.repo.clone());
 886→        }
 887→    }
 888→
 889→    None
 890→}
 891→
 892→/// Detect which workspace the current directory belongs to.
 893→fn detect_workspace(st: &state::WorkspaceState) -> Option<state::WorkspaceEntry> {
 894→    let cwd = std::env::current_dir().ok()?;
 895→
 896→    // Try git root first (handles being in subdirectories)
 897→    let root = std::process::Command::new("git")
 898→        .args(["rev-parse", "--show-toplevel"])
 899→        .output()
 900→        .ok()
 901→        .filter(|o| o.status.success())
 902→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))
 903→        .unwrap_or(cwd);
 904→
 905→    for ws in st.all_workspaces() {
 906→        let ws_dir = st.workspace_dir(ws);
 907→        if ws_dir == root {
 908→            return Some(ws.clone());
 909→        }
 910→    }
 911→    None
 912→}
