  1→use ratatui::Frame;
  2→use ratatui::layout::{Constraint, Layout};
  3→use ratatui::style::{Color, Modifier, Style};
  4→use ratatui::text::{Line, Span};
  5→use ratatui::widgets::{Block, Borders, List, ListItem, ListState, Paragraph};
  6→
  7→use super::app::{App, WorkspaceStatus};
  8→
  9→pub fn render(frame: &mut Frame, app: &App) {
 10→    let area = frame.area();
 11→
 12→    let chunks = Layout::vertical([
 13→        Constraint::Length(1), // header
 14→        Constraint::Min(3),    // workspace list
 15→        Constraint::Length(1), // footer
 16→    ])
 17→    .split(area);
 18→
 19→    // Header
 20→    let header = Paragraph::new(Line::from(vec![
 21→        Span::styled(" dual", Style::default().add_modifier(Modifier::BOLD)),
 22→        Span::raw("  workspace browser"),
 23→    ]));
 24→    frame.render_widget(header, chunks[0]);
 25→
 26→    // Workspace list
 27→    let block = Block::default()
 28→        .borders(Borders::ALL)
 29→        .border_style(Style::default().fg(Color::DarkGray));
 30→
 31→    let items = app.flatten_items();
 32→
 33→    if items.is_empty() {
 34→        let empty = Paragraph::new("  No workspaces. Run `dual add` in a repo to get started.")
 35→            .block(block);
 36→        frame.render_widget(empty, chunks[1]);
 37→    } else {
 38→        let list_items: Vec<ListItem> = items
 39→            .iter()
 40→            .map(|item| {
 41→                let style = match item.status {
 42→                    Some(WorkspaceStatus::Running) => Style::default().fg(Color::Green),
 43→                    Some(WorkspaceStatus::Stopped) => Style::default().fg(Color::Yellow),
 44→                    Some(WorkspaceStatus::Lazy) => Style::default().fg(Color::DarkGray),
 45→                    None => Style::default().add_modifier(Modifier::BOLD), // repo header
 46→                };
 47→                ListItem::new(Line::from(Span::styled(&item.display, style)))
 48→            })
 49→            .collect();
 50→
 51→        let list = List::new(list_items)
 52→            .block(block)
 53→            .highlight_style(
 54→                Style::default()
 55→                    .add_modifier(Modifier::REVERSED)
 56→                    .add_modifier(Modifier::BOLD),
 57→            )
 58→            .highlight_symbol("▸ ");
 59→
 60→        let mut list_state = ListState::default();
 61→        list_state.select(Some(app.selected()));
 62→
 63→        frame.render_stateful_widget(list, chunks[1], &mut list_state);
 64→    }
 65→
 66→    // Footer keybindings
 67→    let footer = Paragraph::new(Line::from(vec![
 68→        Span::styled(" j/k", Style::default().add_modifier(Modifier::BOLD)),
 69→        Span::raw(" navigate  "),
