160→/// Handle a single HTTP request by proxying to the correct container.
161→async fn handle_request(
162→    state: Arc<ProxyState>,
163→    port: u16,
164→    req: Request<Incoming>,
165→) -> Result<Response<Full<Bytes>>, hyper::Error> {
166→    // Extract subdomain from Host header
167→    let host = req
168→        .headers()
169→        .get("host")
170→        .and_then(|h| h.to_str().ok())
171→        .unwrap_or("");
172→
173→    let subdomain = extract_subdomain(host);
174→    debug!(host, port, "routing request");
175→
176→    let container_ip = match subdomain.and_then(|s| state.resolve(port, s)) {
177→        Some(ip) => ip.to_string(),
178→        None => {
179→            let body = format!(
180→                "No route for host: {host}\n\nAvailable routes on port {port}:\n{}",
181→                state
182→                    .routes
183→                    .get(&port)
184→                    .map(|m| m
185→                        .keys()
186→                        .map(|s| format!("  {s}.localhost:{port}"))
187→                        .collect::<Vec<_>>()
188→                        .join("\n"))
189→                    .unwrap_or_default()
190→            );
191→            return Ok(bad_gateway(body));
192→        }
193→    };
194→
195→    // Forward the request to the container
196→    let target_uri = format!(
197→        "http://{}:{}{}",
198→        container_ip,
199→        port,
200→        req.uri()
201→            .path_and_query()
202→            .map(|pq| pq.as_str())
203→            .unwrap_or("/")
204→    );
205→
206→    // Use a TCP connection to the container
207→    let stream = match tokio::net::TcpStream::connect(format!("{container_ip}:{port}")).await {
208→        Ok(s) => s,
209→        Err(e) => {
210→            let body = format!("Cannot connect to {container_ip}:{port}: {e}");
211→            return Ok(bad_gateway(body));
212→        }
213→    };
214→
215→    let io = TokioIo::new(stream);
216→
217→    let (mut sender, conn) = match hyper::client::conn::http1::handshake(io).await {
218→        Ok(c) => c,
219→        Err(e) => {
220→            let body = format!("Handshake failed with {container_ip}:{port}: {e}");
221→            return Ok(bad_gateway(body));
222→        }
223→    };
224→
225→    // Drive the connection in the background
226→    tokio::spawn(async move {
227→        if let Err(e) = conn.await
228→            && !e.to_string().contains("connection closed")
229→        {
230→            warn!("backend connection error: {e}");
231→        }
232→    });
233→
234→    // Forward request
235→    let _ = target_uri; // URI used for logging context
236→    match sender.send_request(req).await {
237→        Ok(resp) => {
238→            // Collect the response body
239→            let (parts, body) = resp.into_parts();
240→            match body.collect().await {
241→                Ok(collected) => Ok(Response::from_parts(parts, Full::new(collected.to_bytes()))),
242→                Err(e) => {
243→                    let body = format!("Error reading response: {e}");
244→                    Ok(bad_gateway(body))
245→                }
246→            }
247→        }
248→        Err(e) => {
249→            let body = format!("Proxy error: {e}");
250→            Ok(bad_gateway(body))
251→        }
252→    }
253→}
