  28→        .with_env_filter(
  29→            tracing_subscriber::EnvFilter::try_from_env("DUAL_LOG")
  30→                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
  31→        )
  32→        .without_time()
  33→        .with_target(false)
  34→        .init();
  35→
  36→    // One-time post-install: ensure shell hook is installed
  37→    match shell::install_shell_hook() {
  38→        Ok(true) => {
  39→            let rc_name = shell::detect_shell_rc()
  40→                .map(|p| {
  41→                    p.file_name()
  42→                        .unwrap_or_default()
  43→                        .to_string_lossy()
  44→                        .to_string()
  45→                })
  46→                .unwrap_or_default();
  47→            info!("Installed shell hook in ~/{rc_name} for tmux pane interception.");
  48→        }
  49→        Ok(false) => {} // Already installed or unsupported shell
  50→        Err(e) => warn!("could not install shell hook: {e}"),
  51→    }
  52→
  53→    let cli = Cli::parse();
  54→    let backend = TmuxBackend::new();
  55→
  56→    let exit_code = match cli.command {
  57→        None => cmd_default(&backend),
  58→        Some(Command::Init { name }) => cmd_init(name.as_deref()),
  59→        Some(Command::Create { branch, repo }) => cmd_create(repo.as_deref(), &branch),
  60→        Some(Command::Launch { workspace }) => cmd_launch(workspace.as_deref(), &backend),
  61→        Some(Command::List) => cmd_list(&backend),
  62→        Some(Command::Destroy { workspace }) => cmd_destroy(workspace.as_deref(), &backend),
  63→        Some(Command::Open { workspace }) => cmd_open(workspace),
  64→        Some(Command::Urls { workspace }) => cmd_urls(workspace),
  65→        Some(Command::Sync { workspace }) => cmd_sync(workspace),
  66→        Some(Command::Proxy) => cmd_proxy(),
  67→        Some(Command::ShellRc { container }) => cmd_shell_rc(&container),
  68→    };
  69→
  70→    std::process::exit(exit_code);
  71→}
  72→
  73→/// Default (no subcommand): launch TUI workspace browser.
  74→///
  75→/// Implements a suspend/resume loop:
  76→/// 1. Show TUI → user selects workspace
  77→/// 2. TUI suspends (ratatui::restore) → launch workspace → tmux attach (blocks)
  78→/// 3. User detaches from tmux → control returns → loop back to step 1
  79→///
  80→/// If already inside tmux, switch-client is instant (non-blocking),
  81→/// so we exit after launch instead of looping.
  82→fn cmd_default(backend: &dyn MultiplexerBackend) -> i32 {
  83→    let inside_tmux = backend.is_inside();
  84→
  85→    loop {
  86→        // Reload state each iteration (workspaces may have changed while in tmux)
  87→        let st = match state::load() {
  88→            Ok(s) => s,
  89→            Err(e) => {
  90→                error!("{e}");
  91→                info!("Run `dual init` inside a repo to get started.");
  92→                return 1;
  93→            }
  94→        };
  95→
  96→        if st.all_workspaces().is_empty() {
  97→            info!("No workspaces. Run `dual init` inside a repo to get started.");
  98→            return 0;
  99→        }
 100→
 101→        match tui::run(&st, backend) {
 102→            Ok(Some(workspace_id)) => {
 103→                // TUI already called ratatui::restore() — terminal is in normal mode
 104→                let exit_code = cmd_launch(Some(&workspace_id), backend);
 105→
 106→                if inside_tmux {
 107→                    // switch-client is instant — don't loop back to TUI
 108→                    return exit_code;
 109→                }
 110→
 111→                if exit_code != 0 {
 112→                    eprintln!("Launch failed (exit code {exit_code}). Press Enter to continue...");
 113→                    let _ = std::io::stdin().read_line(&mut String::new());
 114→                }
 115→
 116→                // tmux attach returned (user detached) — loop back to TUI
 117→                continue;
 118→            }
 119→            Ok(None) => return 0, // User quit
 120→            Err(e) => {
 121→                error!("TUI error: {e}");
 122→                return 1;
 123→            }
 124→        }
 125→    }
 126→}
