 297→/// Launch a specific workspace: clone → container → shell RC → tmux → attach.
 298→fn cmd_launch(workspace_arg: Option<&str>, backend: &dyn MultiplexerBackend) -> i32 {
 299→    let st = match state::load() {
 300→        Ok(s) => s,
 301→        Err(e) => {
 302→            error!("{e}");
 303→            return 1;
 304→        }
 305→    };
 306→
 307→    // Resolve workspace: use arg if provided, otherwise auto-detect from cwd
 308→    let entry = if let Some(ws) = workspace_arg {
 309→        match st.resolve_workspace(ws) {
 310→            Some(e) => e,
 311→            None => {
 312→                error!("unknown workspace '{ws}'");
 313→                info!("Configured workspaces:");
 314→                for w in st.all_workspaces() {
 315→                    let id = config::workspace_id(&w.repo, &w.branch);
 316→                    info!("  {id}");
 317→                }
 318→                return 1;
 319→            }
 320→        }
 321→    } else {
 322→        match detect_workspace(&st) {
 323→            Some(e) => {
 324→                let ws_id = config::workspace_id(&e.repo, &e.branch);
 325→                info!("Auto-detected workspace: {ws_id}");
 326→                st.resolve_workspace(&ws_id).unwrap()
 327→            }
 328→            None => {
 329→                error!("could not detect workspace from current directory");
 330→                info!("Usage: dual launch [workspace]");
 331→                return 1;
 332→            }
 333→        }
 334→    };
 335→
 336→    let workspace_root = st.workspace_root();
 337→    let container_name = config::container_name(&entry.repo, &entry.branch);
 338→    let session_name = config::session_name(&entry.repo, &entry.branch);
 339→    debug!(
 340→        repo = %entry.repo,
 341→        branch = %entry.branch,
 342→        "resolved workspace"
 343→    );
 344→
 345→    // Step 1: Resolve workspace directory
 346→    let workspace_dir = if let Some(ref path) = entry.path {
 347→        let dir = PathBuf::from(path);
 348→        if !dir.join(".git").exists() {
 349→            error!(
 350→                "workspace path {} does not contain a git repo",
 351→                dir.display()
 352→            );
 353→            return 1;
 354→        }
 355→        dir
 356→    } else {
 357→        // Try to clone from local main workspace first (fast, hardlinks)
 358→        let target_dir = config::workspace_dir(&workspace_root, &entry.repo, &entry.branch);
 359→        let main_workspace_path = st
 360→            .workspaces_for_repo(&entry.repo)
 361→            .into_iter()
 362→            .find(|ws| ws.path.is_some())
 363→            .and_then(|ws| ws.path.as_ref().map(PathBuf::from));
 364→
 365→        match main_workspace_path {
 366→            Some(main_path) if main_path.join(".git").exists() => {
 367→                info!("Cloning from local main workspace...");
 368→                match clone::clone_from_local(&main_path, &target_dir, &entry.branch) {
 369→                    Ok(dir) => dir,
 370→                    Err(e) => {
 371→                        error!("local clone failed: {e}");
 372→                        return 1;
 373→                    }
 374→                }
 375→            }
 376→            _ => {
 377→                // Fallback: clone from remote URL
 378→                match clone::clone_workspace(
 379→                    &workspace_root,
 380→                    &entry.repo,
 381→                    &entry.url,
 382→                    &entry.branch,
 383→                ) {
 384→                    Ok(dir) => dir,
 385→                    Err(e) => {
 386→                        error!("clone failed: {e}");
 387→                        return 1;
 388→                    }
 389→                }
 390→            }
 391→        }
 392→    };
 393→
 394→    // Step 2: Handle shared files
 395→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
 396→    if !hints.shared.is_empty()
 397→        && let Ok(shared_dir) = shared::ensure_shared_dir(&entry.repo)
 398→    {
 399→        if entry.path.is_some() {
 400→            // Main workspace: ensure shared files are initialized
 401→            match shared::init_from_main(&workspace_dir, &shared_dir, &hints.shared) {
 402→                Ok(moved) => {
 403→                    for f in &moved {
 404→                        info!("  shared: {f} → ~/.dual/shared/{}/", entry.repo);
 405→                    }
 406→                }
 407→                Err(e) => warn!("shared init failed: {e}"),
 408→            }
 409→        } else {
 410→            // Branch workspace: copy shared files
 411→            match shared::copy_to_branch(&workspace_dir, &shared_dir, &hints.shared) {
 412→                Ok(copied) => {
 413→                    for f in &copied {
 414→                        info!("  shared: copied {f}");
 415→                    }
 416→                }
 417→                Err(e) => warn!("shared copy failed: {e}"),
 418→            }
 419→        }
 420→    }
 421→
 422→    // Step 3: Ensure container exists and is running
 423→    let is_new_container = matches!(
 424→        container::status(&container_name),
 425→        container::ContainerStatus::Missing
 426→    );
 427→    match container::status(&container_name) {
 428→        container::ContainerStatus::Missing => {
 429→            // Build image from Dockerfile if configured
 430→            let effective_image = if let Some(ref build) = hints.dockerfile {
 431→                let image_tag = format!("dual-build-{container_name}");
 432→                info!("Building image from Dockerfile...");
 433→                match container::build_image(&image_tag, &workspace_dir, build) {
 434→                    Ok(tag) => tag,
 435→                    Err(e) => {
 436→                        error!("docker build failed: {e}");
 437→                        return 1;
 438→                    }
 439→                }
 440→            } else {
 441→                hints.image.clone()
 442→            };
 443→
 444→            info!("Creating container {container_name}...");
 445→            if let Err(e) = container::create(
 446→                &container_name,
 447→                &workspace_dir,
 448→                &effective_image,
 449→                &hints.env,
 450→                &hints.anonymous_volumes,
 451→            ) {
 452→                error!("container create failed: {e}");
 453→                return 1;
 454→            }
 455→            if let Err(e) = container::start(&container_name) {
 456→                error!("container start failed: {e}");
 457→                return 1;
 458→            }
 459→        }
 460→        container::ContainerStatus::Stopped => {
 461→            info!("Starting container {container_name}...");
 462→            if let Err(e) = container::start(&container_name) {
 463→                error!("container start failed: {e}");
 464→                return 1;
 465→            }
 466→        }
 467→        container::ContainerStatus::Running => {}
 468→    }
 469→
 470→    // Step 3.5: Run setup command on new containers
 471→    if is_new_container && let Some(ref setup) = hints.setup {
 472→        info!("Running setup: {setup}");
 473→        if let Err(e) = container::exec_setup(&container_name, setup) {
 474→            error!("setup failed: {e}");
 475→            return 1;
 476→        }
 477→    }
 478→
 479→    // Step 4: Write shell RC file
 480→    let rc_path = match shell::write_rc_file(&container_name, &hints.extra_commands) {
 481→        Ok(p) => p,
 482→        Err(e) => {
 483→            error!("failed to write shell RC: {e}");
 484→            return 1;
 485→        }
 486→    };
 487→
 488→    // Step 5: Create tmux session if not alive
 489→    if !backend.is_alive(&session_name) {
 490→        let source_cmd = shell::source_file_command(&rc_path);
 491→        if let Err(e) = backend.create_session(&session_name, &workspace_dir, Some(&source_cmd)) {
 492→            error!("session creation failed: {e}");
 493→            return 1;
 494→        }
 495→
 496→        // Set session-level env vars so new panes auto-source interception
 497→        let rc_path_str = rc_path.to_string_lossy();
 498→        for (key, value) in [
 499→            ("DUAL_ACTIVE", "1"),
 500→            ("DUAL_RC_PATH", rc_path_str.as_ref()),
 501→            ("DUAL_CONTAINER", container_name.as_str()),
 502→        ] {
 503→            if let Err(e) = dual::tmux_backend::set_session_env(&session_name, key, value) {
 504→                warn!("failed to set tmux env {key}: {e}");
 505→            }
 506→        }
 507→    }
 508→
 509→    // Step 6: Attach
 510→    info!("Attaching to {session_name}...");
 511→    if let Err(e) = backend.attach(&session_name) {
 512→        error!("attach failed: {e}");
 513→        return 1;
 514→    }
 515→
 516→    0
 517→}
