 681→    let st = match state::load() {
 682→        Ok(s) => s,
 683→        Err(e) => {
 684→            error!("{e}");
 685→            return 1;
 686→        }
 687→    };
 688→
 689→    let url_groups = proxy::workspace_urls(&st);
 690→    if url_groups.is_empty() {
 691→        info!("No URLs configured. Add 'forwardPorts' to devcontainer.json in your repo.");
 692→        return 0;
 693→    }
 694→
 695→    // Filter by workspace if specified
 696→    let filtered: Vec<_> = match &workspace {
 697→        Some(ws) => url_groups.into_iter().filter(|(id, _)| id == ws).collect(),
 698→        None => url_groups,
 699→    };
 700→
 701→    for (workspace_id, urls) in &filtered {
 702→        info!("{workspace_id}");
 703→        for url in urls {
 704→            info!("{url}");
 705→        }
 706→        info!("");
