 861→/// Detect the repo name from the current working directory.
 862→///
 863→/// Matches the git remote URL of the cwd against known workspace URLs in state.
 864→fn detect_repo_from_cwd(st: &state::WorkspaceState) -> Option<String> {
 865→    let (_, url, _) = detect_git_repo().ok()?;
 866→
 867→    // Match against known workspace URLs
 868→    for ws in st.all_workspaces() {
 869→        if ws.url == url {
 870→            return Some(ws.repo.clone());
 871→        }
 872→    }
 873→
 874→    // Also try matching by git root path against workspace paths
 875→    let cwd = std::env::current_dir().ok()?;
 876→    let root = std::process::Command::new("git")
 877→        .args(["rev-parse", "--show-toplevel"])
 878→        .output()
 879→        .ok()
 880→        .filter(|o| o.status.success())
 881→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))?;
 882→
 883→    for ws in st.all_workspaces() {
 884→        let ws_dir = st.workspace_dir(ws);
 885→        if ws_dir == root || ws_dir == cwd {
 886→            return Some(ws.repo.clone());
 887→        }
 888→    }
 889→
 890→    None
 891→}
 892→
 893→/// Detect which workspace the current directory belongs to.
 894→fn detect_workspace(st: &state::WorkspaceState) -> Option<state::WorkspaceEntry> {
 895→    let cwd = std::env::current_dir().ok()?;
 896→
 897→    // Try git root first (handles being in subdirectories)
 898→    let root = std::process::Command::new("git")
 899→        .args(["rev-parse", "--show-toplevel"])
 900→        .output()
 901→        .ok()
 902→        .filter(|o| o.status.success())
 903→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))
 904→        .unwrap_or(cwd);
 905→
 906→    for ws in st.all_workspaces() {
 907→        let ws_dir = st.workspace_dir(ws);
 908→        if ws_dir == root {
 909→            return Some(ws.clone());
 910→        }
 911→    }
 912→    None
 913→}
