 71→/// Per-repo runtime hints — the merged internal representation used by all consumers.
 72→///
 73→/// Built from DualConfig (.dual/settings.json) + DevcontainerJson (devcontainer.json).
 74→/// Consumer code (container, proxy, shell) uses this struct exclusively.
 75→#[derive(Debug, Serialize, Deserialize, PartialEq, Clone)]
 76→pub struct RepoHints {
 77→    /// Docker image to use for containers (default: "node:20")
 78→    #[serde(default = "default_image")]
 79→    pub image: String,
 80→
 81→    /// Ports that services bind to inside the container
 82→    #[serde(default)]
 83→    pub ports: Vec<u16>,
 84→
 85→    /// Setup command to run after container creation (e.g. "pnpm install")
 86→    pub setup: Option<String>,
 87→
 88→    /// Environment variables for the container
 89→    #[serde(default)]
 90→    pub env: HashMap<String, String>,
 91→
 92→    /// Additional commands to route to the container (merged with defaults)
 93→    #[serde(default)]
 94→    pub extra_commands: Vec<String>,
 95→
 96→    /// Directories to isolate with anonymous Docker volumes
 97→    #[serde(default = "default_anonymous_volumes")]
 98→    pub anonymous_volumes: Vec<String>,
 99→
100→    /// Shared files to propagate across workspaces
101→    #[serde(default)]
102→    pub shared: Vec<String>,
103→
104→    /// Dockerfile build config — if set, build image instead of pulling.
105→    /// Sourced from devcontainer.json build field.
106→    #[serde(skip_serializing_if = "Option::is_none")]
107→    pub dockerfile: Option<DockerfileBuild>,
108→}
109→
110→fn default_image() -> String {
111→    DEFAULT_IMAGE.to_string()
112→}
113→
114→fn default_anonymous_volumes() -> Vec<String> {
115→    vec!["node_modules".to_string()]
116→}
117→
118→impl Default for RepoHints {
119→    fn default() -> Self {
120→        Self {
121→            image: DEFAULT_IMAGE.to_string(),
122→            ports: Vec::new(),
123→            setup: None,
124→            env: HashMap::new(),
125→            extra_commands: Vec::new(),
126→            anonymous_volumes: default_anonymous_volumes(),
127→            shared: Vec::new(),
128→            dockerfile: None,
129→        }
130→    }
131→}
