133→/// Get the shared config directory for a repo: ~/.dual/shared/{repo}/
134→pub fn shared_dir(repo: &str) -> Option<PathBuf> {
135→    dirs::home_dir().map(|home| home.join(".dual").join("shared").join(repo))
136→}
137→
138→/// Load RepoHints from a workspace directory.
139→///
140→/// Loading flow:
141→/// 1. Read `.dual/settings.json` → `DualConfig` (error if missing)
142→/// 2. Use explicit devcontainer path from DualConfig
143→/// 3. Parse devcontainer.json → `RepoHints` for container fields
144→/// 4. Merge DualConfig fields + devcontainer RepoHints → final `RepoHints`
145→pub fn load_hints(workspace_dir: &Path) -> Result<RepoHints, HintsError> {
146→    let dual_config = load_dual_config(workspace_dir)?;
147→    let dc_path = workspace_dir.join(&dual_config.devcontainer);
148→
149→    // Load container config from devcontainer.json
150→    let dc_hints = if dc_path.exists() {
151→        let devcontainer_dir = dc_path.parent().unwrap_or(workspace_dir);
152→        let contents = std::fs::read_to_string(&dc_path).ok();
153→        contents.and_then(|c| {
154→            let dc = crate::devcontainer::parse_devcontainer(&c).ok()?;
155→            Some(crate::devcontainer::to_repo_hints(&dc, devcontainer_dir))
156→        })
157→    } else {
158→        warn!(
159→            "devcontainer.json not found at '{}' (specified in .dual/settings.json)",
160→            dc_path.display()
161→        );
162→        None
163→    };
164→
165→    Ok(merge_config(&dual_config, dc_hints.as_ref()))
166→}
167→
168→/// Load DualConfig from .dual/settings.json. Returns error if file doesn't exist.
169→fn load_dual_config(workspace_dir: &Path) -> Result<DualConfig, HintsError> {
170→    let path = workspace_dir.join(DUAL_DIR).join(SETTINGS_FILENAME);
171→
172→    if !path.exists() {
173→        return Err(HintsError::MissingConfig(workspace_dir.to_path_buf()));
174→    }
175→
176→    let contents =
177→        std::fs::read_to_string(&path).map_err(|e| HintsError::ReadError(path.clone(), e))?;
178→
179→    let config: DualConfig =
180→        serde_json::from_str(&contents).map_err(|e| HintsError::JsonParseError(path, e))?;
181→    Ok(config)
182→}
183→
184→/// Merge DualConfig + devcontainer RepoHints into final RepoHints.
185→///
186→/// devcontainer.json provides: image, ports, setup, env, dockerfile
187→/// DualConfig provides: extra_commands, anonymous_volumes, shared
188→fn merge_config(dual: &DualConfig, dc_hints: Option<&RepoHints>) -> RepoHints {
189→    let base = dc_hints.cloned().unwrap_or_default();
190→
191→    RepoHints {
192→        // Container fields come from devcontainer.json (or defaults)
193→        image: base.image,
194→        ports: base.ports,
195→        setup: base.setup,
196→        env: base.env,
197→        dockerfile: base.dockerfile,
198→
199→        // Dual-specific fields come from .dual/settings.json
200→        extra_commands: dual.extra_commands.clone(),
201→        anonymous_volumes: dual.anonymous_volumes.clone(),
202→        shared: dual.shared.clone(),
203→    }
204→}
205→
206→/// Write a default .dual/settings.json with Dual-specific fields only.
207→/// Container config belongs in devcontainer.json.
208→/// Creates the .dual/ directory if it doesn't exist.
209→pub fn write_default_dual_config(
210→    repo_root: &Path,
211→    devcontainer_path: &str,
212→) -> Result<(), HintsError> {
213→    let dual_dir = repo_root.join(DUAL_DIR);
214→    std::fs::create_dir_all(&dual_dir).map_err(|e| HintsError::WriteError(dual_dir.clone(), e))?;
215→
216→    let config = DualConfig {
217→        devcontainer: devcontainer_path.to_string(),
218→        ..Default::default()
219→    };
220→
221→    let path = dual_dir.join(SETTINGS_FILENAME);
222→    let contents = serde_json::to_string_pretty(&config).map_err(HintsError::JsonSerializeError)?;
223→    std::fs::write(&path, contents).map_err(|e| HintsError::WriteError(path, e))?;
224→    Ok(())
225→}
226→
227→/// Write a default devcontainer.json with minimal container config.
228→/// Creates .devcontainer/ directory if it doesn't exist.
229→pub fn write_default_devcontainer(repo_root: &Path) -> Result<(), HintsError> {
230→    let dc_dir = repo_root.join(".devcontainer");
231→    std::fs::create_dir_all(&dc_dir).map_err(|e| HintsError::WriteError(dc_dir.clone(), e))?;
232→
233→    let dc_path = dc_dir.join("devcontainer.json");
234→    let content = r#"{
235→    "image": "node:20"
236→}
237→"#;
238→    std::fs::write(&dc_path, content).map_err(|e| HintsError::WriteError(dc_path, e))?;
239→    Ok(())
240→}
241→
242→/// Write DualConfig to a workspace directory's .dual/settings.json.
243→pub fn write_dual_config(workspace_dir: &Path, config: &DualConfig) -> Result<(), HintsError> {
244→    let dual_dir = workspace_dir.join(DUAL_DIR);
245→    std::fs::create_dir_all(&dual_dir).map_err(|e| HintsError::WriteError(dual_dir.clone(), e))?;
246→
247→    let path = dual_dir.join(SETTINGS_FILENAME);
248→    let contents = serde_json::to_string_pretty(config).map_err(HintsError::JsonSerializeError)?;
249→    std::fs::write(&path, contents).map_err(|e| HintsError::WriteError(path, e))?;
250→    Ok(())
251→}
252→
253→/// Parse DualConfig from JSON string (for testing).
254→pub fn parse_dual_config(json_str: &str) -> Result<DualConfig, HintsError> {
255→    let config: DualConfig = serde_json::from_str(json_str)
256→        .map_err(|e| HintsError::JsonParseError(PathBuf::from("<string>"), e))?;
257→    Ok(config)
258→}
