260→/// Compute the workspace identifier from repo + branch.
261→/// e.g. ("lightfast", "feat/auth") → "lightfast-feat__auth"
262→pub fn workspace_id(repo: &str, branch: &str) -> String {
263→    format!("{}-{}", repo, encode_branch(branch))
264→}
265→
266→/// Get the workspace directory for a repo + branch combination.
267→/// Layout: {workspace_root}/{repo}/{encoded_branch}/
268→pub fn workspace_dir(workspace_root: &Path, repo: &str, branch: &str) -> PathBuf {
269→    workspace_root.join(repo).join(encode_branch(branch))
270→}
271→
272→/// Compute the container name for a repo + branch combination.
273→/// Pattern: dual-{repo}-{encoded_branch}
274→pub fn container_name(repo: &str, branch: &str) -> String {
275→    format!("dual-{}-{}", repo, encode_branch(branch))
276→}
277→
278→/// Compute the tmux session name for a repo + branch combination.
279→/// Uses the same naming convention as container names for consistency.
280→pub fn session_name(repo: &str, branch: &str) -> String {
281→    container_name(repo, branch)
282→}
283→
284→/// Encode a branch name for filesystem use.
285→/// Replaces `/` with `__` (double underscore).
286→/// e.g. "feat/auth" → "feat__auth"
287→pub fn encode_branch(branch: &str) -> String {
288→    branch.replace('/', "__")
289→}
290→
291→/// Decode an encoded branch name back to the original.
292→/// Replaces `__` with `/`.
293→/// e.g. "feat__auth" → "feat/auth"
294→pub fn decode_branch(encoded: &str) -> String {
295→    encoded.replace("__", "/")
296→}
297→
298→#[derive(Debug, thiserror::Error)]
299→pub enum HintsError {
300→    #[error("Failed to read {path}: {err}", path = .0.display(), err = .1)]
301→    ReadError(PathBuf, std::io::Error),
302→
303→    #[error("Failed to write {path}: {err}", path = .0.display(), err = .1)]
304→    WriteError(PathBuf, std::io::Error),
305→
306→    #[error("Failed to parse {path}: {err}", path = .0.display(), err = .1)]
307→    JsonParseError(PathBuf, serde_json::Error),
308→
309→    #[error("Failed to serialize config: {0}")]
310→    JsonSerializeError(serde_json::Error),
311→
312→    #[error("No .dual/settings.json found in {path}. Run `dual init` first.", path = .0.display())]
313→    MissingConfig(PathBuf),
314→}
