263→/// Build docker build arguments (public for testing).
264→pub fn build_image_args(
265→    tag: &str,
266→    workspace_dir: &Path,
267→    build: &crate::config::DockerfileBuild,
268→) -> Vec<String> {
269→    // Resolve paths relative to base_dir (devcontainer.json location) or workspace root
270→    let base = build.base_dir.as_deref().unwrap_or(workspace_dir);
271→
272→    let dockerfile_path = base.join(&build.path);
273→    let context_path = base.join(&build.context);
274→
275→    let mut args = vec![
276→        "build".to_string(),
277→        "-t".to_string(),
278→        tag.to_string(),
279→        "-f".to_string(),
280→        dockerfile_path.display().to_string(),
281→    ];
282→
283→    // Build arguments
284→    for (key, value) in &build.args {
285→        args.push("--build-arg".to_string());
286→        args.push(format!("{key}={value}"));
287→    }
288→
289→    // Target stage
290→    if let Some(ref target) = build.target {
291→        args.push("--target".to_string());
292→        args.push(target.clone());
293→    }
294→
295→    // Build context (last argument)
296→    args.push(context_path.display().to_string());
297→
298→    args
299→}
