 85→/// Generate a shell command to source the RC content from a string.
 86→/// Useful for injecting into tmux pane creation.
 87→pub fn source_command(container_name: &str) -> String {
 88→    format!("eval \"$(dual shell-rc {container_name})\"")
 89→}
 90→
 91→/// Write the shell RC to a file and return the path.
 92→/// RC files are written to ~/.dual/rc/{container_name}.sh
 93→pub fn write_rc_file(
 94→    container_name: &str,
 95→    extra_commands: &[String],
 96→) -> Result<std::path::PathBuf, std::io::Error> {
 97→    let rc_dir = dirs::home_dir()
 98→        .unwrap_or_else(|| std::path::PathBuf::from("."))
 99→        .join(".dual")
100→        .join("rc");
101→    std::fs::create_dir_all(&rc_dir)?;
102→
103→    let rc_path = rc_dir.join(format!("{container_name}.sh"));
104→    let rc_content = generate_rc(container_name, extra_commands);
105→    std::fs::write(&rc_path, rc_content)?;
106→
107→    Ok(rc_path)
108→}
109→
110→/// Marker comment used to detect if the snippet is already installed.
111→const RC_MARKER: &str = "# dual: shell interception (auto-generated)";
112→
113→/// Generate the shell RC snippet that auto-sources Dual interception.
114→///
115→/// This snippet is appended to ~/.bashrc or ~/.zshrc. It detects
116→/// the DUAL_ACTIVE env var (set by tmux set-environment) and sources
117→/// the workspace-specific RC file.
118→pub fn shell_hook_snippet() -> String {
119→    format!(
120→        r#"
121→{RC_MARKER}
122→if [ -n "$DUAL_ACTIVE" ] && [ -n "$DUAL_RC_PATH" ] && [ -f "$DUAL_RC_PATH" ]; then
123→    source "$DUAL_RC_PATH"
124→fi
125→"#
126→    )
127→}
128→
129→/// Detect the user's shell RC file path.
130→///
131→/// Returns the path to ~/.zshrc or ~/.bashrc based on $SHELL.
132→/// Returns None if the shell is not bash or zsh.
133→pub fn detect_shell_rc() -> Option<std::path::PathBuf> {
134→    let home = dirs::home_dir()?;
135→    let shell = std::env::var("SHELL").unwrap_or_default();
136→    let base = shell.rsplit('/').next().unwrap_or("");
137→
138→    match base {
139→        "zsh" => Some(home.join(".zshrc")),
140→        "bash" => Some(home.join(".bashrc")),
141→        _ => None,
142→    }
143→}
144→
145→/// Install the auto-source snippet into the user's shell RC file.
146→///
147→/// Idempotent: checks for the marker comment before appending.
148→/// Creates the RC file if it doesn't exist.
149→/// Returns Ok(true) if the snippet was newly installed, Ok(false) if
150→/// already present.
151→pub fn install_shell_hook() -> Result<bool, std::io::Error> {
152→    let rc_path = match detect_shell_rc() {
153→        Some(p) => p,
154→        None => return Ok(false),
155→    };
156→
157→    // Read existing content (or empty if file doesn't exist)
158→    let existing = std::fs::read_to_string(&rc_path).unwrap_or_default();
159→
160→    // Check if snippet is already installed
161→    if existing.contains(RC_MARKER) {
162→        return Ok(false);
163→    }
164→
165→    // Append snippet
166→    use std::io::Write;
167→    let mut file = std::fs::OpenOptions::new()
168→        .create(true)
169→        .append(true)
170→        .open(&rc_path)?;
171→    file.write_all(shell_hook_snippet().as_bytes())?;
172→
173→    Ok(true)
174→}
175→
176→/// Get the source command for an RC file path.
177→pub fn source_file_command(rc_path: &std::path::Path) -> String {
178→    format!("source \"{}\"", rc_path.display())
179→}
