 19→/// Build a 502 Bad Gateway response with a text body.
 20→fn bad_gateway(body: impl Into<String>) -> Response<Full<Bytes>> {
 21→    Response::builder()
 22→        .status(StatusCode::BAD_GATEWAY)
 23→        .body(Full::new(Bytes::from(body.into())))
 24→        .expect("valid status code always produces valid response")
 25→}
 26→
 27→/// Routing entry: subdomain → container IP.
 28→type RouteMap = HashMap<String, String>;
 29→
 30→/// Full routing state: port → (subdomain → container_ip).
 31→pub struct ProxyState {
 32→    /// Map of port → RouteMap (subdomain → container_ip).
 33→    pub routes: HashMap<u16, RouteMap>,
 34→}
 35→
 36→impl ProxyState {
 37→    /// Build routing table from workspace state and running containers.
 38→    pub fn from_state(state: &WorkspaceState) -> Self {
 39→        let mut routes: HashMap<u16, RouteMap> = HashMap::new();
 40→
 41→        for entry in state.all_workspaces() {
 42→            let container_name = config::container_name(&entry.repo, &entry.branch);
 43→
 44→            // Only route to running containers
 45→            if container::status(&container_name) != container::ContainerStatus::Running {
 46→                continue;
 47→            }
 48→
 49→            let ip = match container::get_ip(&container_name) {
 50→                Some(ip) => ip,
 51→                None => continue,
 52→            };
 53→
 54→            // Load hints to get ports
 55→            let ws_dir = state.workspace_dir(entry);
 56→            let hints = config::load_hints(&ws_dir).unwrap_or_default();
 57→
 58→            let workspace_id = config::workspace_id(&entry.repo, &entry.branch);
 59→            for &port in &hints.ports {
 60→                routes
 61→                    .entry(port)
 62→                    .or_default()
 63→                    .insert(workspace_id.clone(), ip.clone());
 64→            }
 65→        }
 66→
 67→        ProxyState { routes }
 68→    }
 69→
 70→    /// Get the container IP for a given port and subdomain.
 71→    pub fn resolve(&self, port: u16, subdomain: &str) -> Option<&str> {
 72→        self.routes
 73→            .get(&port)
 74→            .and_then(|m| m.get(subdomain))
 75→            .map(|s| s.as_str())
 76→    }
 77→
 78→    /// Get all unique ports that need listeners.
 79→    pub fn ports(&self) -> Vec<u16> {
 80→        self.routes.keys().copied().collect()
 81→    }
 82→}
 83→
 84→/// Start the reverse proxy, listening on all configured ports.
 85→pub async fn start(state: &WorkspaceState) -> Result<(), Box<dyn std::error::Error>> {
 86→    let proxy_state = ProxyState::from_state(state);
 87→    let ports = proxy_state.ports();
 88→
 89→    if ports.is_empty() {
 90→        info!(
 91→            "No ports configured for proxy. Add 'forwardPorts' to devcontainer.json in your repo."
 92→        );
 93→        info!("Example .devcontainer/devcontainer.json:");
 94→        info!("  {{\"image\": \"node:20\", \"forwardPorts\": [3000, 3001]}}");
 95→        return Ok(());
 96→    }
 97→
 98→    let proxy_state = Arc::new(proxy_state);
 99→
100→    info!("Starting reverse proxy...");
101→    info!("Routes:");
102→    for (&port, routes) in &proxy_state.routes {
103→        for (subdomain, ip) in routes {
104→            info!("  {subdomain}.localhost:{port} → {ip}:{port}");
105→        }
106→    }
107→
108→    let mut handles = Vec::new();
109→
110→    for port in ports {
111→        let state = Arc::clone(&proxy_state);
112→        let addr = SocketAddr::from(([127, 0, 0, 1], port));
113→
114→        let listener = TcpListener::bind(addr).await?;
115→        info!("Listening on {addr}");
116→
117→        handles.push(tokio::spawn(async move {
118→            loop {
119→                let (stream, _) = match listener.accept().await {
120→                    Ok(conn) => conn,
121→                    Err(e) => {
122→                        warn!(port, "accept error: {e}");
123→                        continue;
124→                    }
125→                };
126→
127→                let state = Arc::clone(&state);
128→                let io = TokioIo::new(stream);
129→
130→                tokio::spawn(async move {
131→                    let service = service_fn(move |req| {
132→                        let state = Arc::clone(&state);
133→                        handle_request(state, port, req)
134→                    });
135→
136→                    if let Err(e) = http1::Builder::new()
137→                        .preserve_header_case(true)
138→                        .serve_connection(io, service)
139→                        .with_upgrades()
140→                        .await
141→                        && !e.to_string().contains("connection closed")
142→                    {
143→                        debug!("connection error: {e}");
144→                    }
145→                });
146→            }
147→        }));
148→    }
149→
150→    info!("Proxy running. Press Ctrl+C to stop.");
151→
152→    // Wait for all listeners (runs forever until Ctrl+C)
153→    for handle in handles {
154→        let _ = handle.await;
155→    }
156→
157→    Ok(())
158→}
159→
160→/// Handle a single HTTP request by proxying to the correct container.
161→async fn handle_request(
162→    state: Arc<ProxyState>,
163→    port: u16,
164→    req: Request<Incoming>,
165→) -> Result<Response<Full<Bytes>>, hyper::Error> {
166→    // Extract subdomain from Host header
167→    let host = req
168→        .headers()
169→        .get("host")
170→        .and_then(|h| h.to_str().ok())
171→        .unwrap_or("");
172→
173→    let subdomain = extract_subdomain(host);
174→    debug!(host, port, "routing request");
175→
176→    let container_ip = match subdomain.and_then(|s| state.resolve(port, s)) {
177→        Some(ip) => ip.to_string(),
178→        None => {
179→            let body = format!(
180→                "No route for host: {host}\n\nAvailable routes on port {port}:\n{}",
181→                state
182→                    .routes
183→                    .get(&port)
184→                    .map(|m| m
185→                        .keys()
186→                        .map(|s| format!("  {s}.localhost:{port}"))
187→                        .collect::<Vec<_>>()
188→                        .join("\n"))
189→                    .unwrap_or_default()
190→            );
191→            return Ok(bad_gateway(body));
192→        }
193→    };
194→
195→    // Forward the request to the container
196→    let target_uri = format!(
197→        "http://{}:{}{}",
198→        container_ip,
199→        port,
200→        req.uri()
201→            .path_and_query()
202→            .map(|pq| pq.as_str())
203→            .unwrap_or("/")
204→    );
205→
206→    // Use a TCP connection to the container
207→    let stream = match tokio::net::TcpStream::connect(format!("{container_ip}:{port}")).await {
208→        Ok(s) => s,
209→        Err(e) => {
210→            let body = format!("Cannot connect to {container_ip}:{port}: {e}");
211→            return Ok(bad_gateway(body));
212→        }
213→    };
214→
215→    let io = TokioIo::new(stream);
216→
217→    let (mut sender, conn) = match hyper::client::conn::http1::handshake(io).await {
218→        Ok(c) => c,
219→        Err(e) => {
220→            let body = format!("Handshake failed with {container_ip}:{port}: {e}");
221→            return Ok(bad_gateway(body));
222→        }
223→    };
224→
225→    // Drive the connection in the background
226→    tokio::spawn(async move {
227→        if let Err(e) = conn.await
228→            && !e.to_string().contains("connection closed")
229→        {
230→            warn!("backend connection error: {e}");
231→        }
232→    });
233→
234→    // Forward request
235→    let _ = target_uri; // URI used for logging context
236→    match sender.send_request(req).await {
237→        Ok(resp) => {
238→            // Collect the response body
239→            let (parts, body) = resp.into_parts();
240→            match body.collect().await {
241→                Ok(collected) => Ok(Response::from_parts(parts, Full::new(collected.to_bytes()))),
242→                Err(e) => {
243→                    let body = format!("Error reading response: {e}");
244→                    Ok(bad_gateway(body))
245→                }
246→            }
247→        }
248→        Err(e) => {
249→            let body = format!("Proxy error: {e}");
250→            Ok(bad_gateway(body))
251→        }
252→    }
253→}
254→
255→/// Extract subdomain from a Host header value.
256→/// "lightfast-main.localhost:3000" → Some("lightfast-main")
257→/// "localhost:3000" → None
258→/// "lightfast-main.localhost" → Some("lightfast-main")
259→fn extract_subdomain(host: &str) -> Option<&str> {
260→    // Strip port if present
261→    let host_part = host.split(':').next().unwrap_or(host);
262→
263→    // Check for .localhost suffix
264→    if let Some(subdomain) = host_part.strip_suffix(".localhost")
265→        && !subdomain.is_empty()
266→    {
267→        return Some(subdomain);
268→    }
269→
270→    None
271→}
