  1→use std::path::{Path, PathBuf};
  2→
  3→/// Ensure the shared directory exists for a repo.
  4→pub fn ensure_shared_dir(repo: &str) -> Result<PathBuf, SharedError> {
  5→    let dir = crate::config::shared_dir(repo).ok_or(SharedError::NoHomeDir)?;
  6→    std::fs::create_dir_all(&dir).map_err(|e| SharedError::Filesystem(dir.clone(), e))?;
  7→    Ok(dir)
  8→}
  9→
 10→/// Initialize shared directory from the main workspace.
 11→///
 12→/// For each file in `files`:
 13→/// - If file exists in workspace and is NOT already a symlink to shared dir:
 14→///   move it to shared dir, create symlink back (Unix) or copy back (Windows)
 15→/// - If file is already a symlink to shared dir: skip
 16→/// - If file doesn't exist in workspace: skip
 17→///
 18→/// Returns list of files that were moved.
 19→pub fn init_from_main(
 20→    workspace_dir: &Path,
 21→    shared_dir: &Path,
 22→    files: &[String],
 23→) -> Result<Vec<String>, SharedError> {
 24→    let mut moved = Vec::new();
 25→
 26→    for file in files {
 27→        let src = workspace_dir.join(file);
 28→        let dst = shared_dir.join(file);
 29→
 30→        if !src.exists() && src.symlink_metadata().is_err() {
 31→            continue; // File not present yet, skip
 32→        }
 33→
 34→        // Check if already a symlink pointing to shared dir
 35→        if src
 36→            .symlink_metadata()
 37→            .map(|m| m.is_symlink())
 38→            .unwrap_or(false)
 39→            && let Ok(target) = std::fs::read_link(&src)
 40→            && target == dst
 41→        {
 42→            continue; // Already set up correctly
 43→        }
 44→
 45→        // Ensure parent dir exists in shared
 46→        if let Some(parent) = dst.parent() {
 47→            std::fs::create_dir_all(parent)
 48→                .map_err(|e| SharedError::Filesystem(parent.to_path_buf(), e))?;
 49→        }
 50→
 51→        // Move file/dir to shared dir
 52→        // Use copy + remove for cross-device moves (rename fails across filesystems)
 53→        copy_recursive(&src, &dst)?;
 54→        remove_recursive(&src)?;
 55→
 56→        // Create symlink back (Unix) or copy back (Windows)
 57→        #[cfg(unix)]
 58→        {
 59→            std::os::unix::fs::symlink(&dst, &src)
 60→                .map_err(|e| SharedError::Filesystem(src.clone(), e))?;
 61→        }
 62→        #[cfg(windows)]
 63→        {
 64→            copy_recursive(&dst, &src)?;
 65→        }
 66→
 67→        moved.push(file.clone());
 68→    }
 69→
 70→    Ok(moved)
 71→}
 72→
 73→/// Copy shared files into a branch workspace.
 74→///
 75→/// For each file in `files`:
 76→/// - If file exists in shared dir: copy to workspace (overwrite if exists)
 77→/// - If file doesn't exist in shared dir: skip
 78→///
 79→/// Returns list of files that were copied.
 80→pub fn copy_to_branch(
 81→    workspace_dir: &Path,
 82→    shared_dir: &Path,
 83→    files: &[String],
 84→) -> Result<Vec<String>, SharedError> {
 85→    let mut copied = Vec::new();
 86→
 87→    for file in files {
 88→        let src = shared_dir.join(file);
 89→        let dst = workspace_dir.join(file);
 90→
 91→        if !src.exists() {
 92→            continue; // Not in shared dir yet, skip
 93→        }
 94→
 95→        // Ensure parent dir exists in workspace
 96→        if let Some(parent) = dst.parent() {
 97→            std::fs::create_dir_all(parent)
 98→                .map_err(|e| SharedError::Filesystem(parent.to_path_buf(), e))?;
 99→        }
100→
101→        // Remove existing destination to handle overwrite cleanly
102→        if dst.exists() || dst.symlink_metadata().is_ok() {
103→            remove_recursive(&dst)?;
104→        }
105→
106→        copy_recursive(&src, &dst)?;
107→        copied.push(file.clone());
108→    }
109→
110→    Ok(copied)
111→}
112→
113→/// Recursively copy a file or directory.
114→fn copy_recursive(src: &Path, dst: &Path) -> Result<(), SharedError> {
115→    let metadata = src
116→        .symlink_metadata()
117→        .map_err(|e| SharedError::Filesystem(src.to_path_buf(), e))?;
118→
119→    if metadata.is_dir() {
120→        std::fs::create_dir_all(dst).map_err(|e| SharedError::Filesystem(dst.to_path_buf(), e))?;
121→
122→        for entry in
123→            std::fs::read_dir(src).map_err(|e| SharedError::Filesystem(src.to_path_buf(), e))?
124→        {
125→            let entry = entry.map_err(|e| SharedError::Filesystem(src.to_path_buf(), e))?;
126→            let child_src = entry.path();
127→            let child_dst = dst.join(entry.file_name());
128→            copy_recursive(&child_src, &child_dst)?;
129→        }
130→    } else {
131→        std::fs::copy(src, dst).map_err(|e| SharedError::Filesystem(src.to_path_buf(), e))?;
132→    }
133→
134→    Ok(())
135→}
136→
137→/// Remove a file or directory.
138→fn remove_recursive(path: &Path) -> Result<(), SharedError> {
139→    let metadata = path
140→        .symlink_metadata()
141→        .map_err(|e| SharedError::Filesystem(path.to_path_buf(), e))?;
142→
143→    if metadata.is_dir() {
144→        std::fs::remove_dir_all(path)
145→            .map_err(|e| SharedError::Filesystem(path.to_path_buf(), e))?;
146→    } else {
147→        std::fs::remove_file(path).map_err(|e| SharedError::Filesystem(path.to_path_buf(), e))?;
148→    }
149→
150→    Ok(())
151→}
