153→#[derive(Debug, thiserror::Error)]
154→pub enum SharedError {
155→    #[error("Could not determine home directory")]
156→    NoHomeDir,
157→
158→    #[error("Filesystem error at {path}: {err}", path = .0.display(), err = .1)]
159→    Filesystem(PathBuf, std::io::Error),
160→}
