  1→use std::path::{Path, PathBuf};
  2→use std::process::Command;
  3→
  4→use crate::config;
  5→
  6→/// Check if a URL looks like a local filesystem path (vs a remote git URL).
  7→pub fn is_local_path(url: &str) -> bool {
  8→    // Local paths: start with /, ./, ../, or ~/ and don't contain ://
  9→    if url.contains("://") {
 10→        return false;
 11→    }
 12→    url.starts_with('/') || url.starts_with("./") || url.starts_with("../") || url.starts_with("~/")
 13→}
 14→
 15→/// Check if a workspace clone already exists on disk.
 16→pub fn workspace_exists(workspace_root: &Path, repo: &str, branch: &str) -> bool {
 17→    let dir = config::workspace_dir(workspace_root, repo, branch);
 18→    dir.join(".git").exists()
 19→}
 20→
 21→/// Create a full git clone for a workspace.
 22→///
 23→/// - Local paths use `git clone --local` for hardlink-based fast clones
 24→/// - Remote URLs use standard `git clone`
 25→/// - Branch is checked out via `-b` flag
 26→/// - Target directory is determined by workspace_root + repo + branch
 27→pub fn clone_workspace(
 28→    workspace_root: &Path,
 29→    repo: &str,
 30→    url: &str,
 31→    branch: &str,
 32→) -> Result<PathBuf, CloneError> {
 33→    let target_dir = config::workspace_dir(workspace_root, repo, branch);
 34→
 35→    // Don't re-clone if it already exists
 36→    if target_dir.join(".git").exists() {
 37→        return Ok(target_dir);
 38→    }
 39→
 40→    // Ensure parent directory exists
 41→    if let Some(parent) = target_dir.parent() {
 42→        std::fs::create_dir_all(parent)
 43→            .map_err(|e| CloneError::Filesystem(parent.to_path_buf(), e))?;
 44→    }
 45→
 46→    let mut cmd = Command::new("git");
 47→    cmd.arg("clone");
 48→
 49→    // Use --local for local paths (hardlinks, fast)
 50→    if is_local_path(url) {
 51→        cmd.arg("--local");
 52→    }
 53→
 54→    // Checkout the specified branch
 55→    cmd.arg("-b").arg(branch);
 56→
 57→    // Source and destination
 58→    cmd.arg(url).arg(&target_dir);
 59→
 60→    let output = cmd
 61→        .output()
 62→        .map_err(|e| CloneError::GitNotFound(e.to_string()))?;
 63→
 64→    if !output.status.success() {
 65→        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
 66→        return Err(CloneError::GitFailed {
 67→            repo: repo.to_string(),
 68→            branch: branch.to_string(),
 69→            stderr,
 70→        });
 71→    }
 72→
 73→    Ok(target_dir)
 74→}
 75→
 76→/// Remove a workspace clone from disk.
 77→pub fn remove_workspace(workspace_root: &Path, repo: &str, branch: &str) -> Result<(), CloneError> {
 78→    let dir = config::workspace_dir(workspace_root, repo, branch);
 79→    if dir.exists() {
 80→        std::fs::remove_dir_all(&dir).map_err(|e| CloneError::Filesystem(dir, e))?;
 81→    }
 82→    Ok(())
 83→}
 84→
 85→/// Clone from a local main workspace using --local (hardlinks), then create a new branch.
 86→///
 87→/// This avoids the problem of `git clone -b <branch>` failing when the branch
 88→/// doesn't exist at the remote. Instead, we clone from the local main workspace
 89→/// and create the branch locally.
 90→pub fn clone_from_local(
 91→    main_workspace_path: &Path,
 92→    target_dir: &Path,
 93→    new_branch: &str,
 94→) -> Result<PathBuf, CloneError> {
 95→    // Don't re-clone if it already exists
 96→    if target_dir.join(".git").exists() {
 97→        return Ok(target_dir.to_path_buf());
 98→    }
 99→
100→    // Ensure parent directory exists
101→    if let Some(parent) = target_dir.parent() {
102→        std::fs::create_dir_all(parent)
103→            .map_err(|e| CloneError::Filesystem(parent.to_path_buf(), e))?;
104→    }
105→
106→    // Step 1: git clone --local <main_workspace_path> <target_dir>
107→    let clone_output = Command::new("git")
108→        .args(build_local_clone_args(main_workspace_path, target_dir))
109→        .output()
110→        .map_err(|e| CloneError::GitNotFound(e.to_string()))?;
111→
112→    if !clone_output.status.success() {
113→        let stderr = String::from_utf8_lossy(&clone_output.stderr).to_string();
114→        return Err(CloneError::GitFailed {
115→            repo: main_workspace_path.to_string_lossy().to_string(),
116→            branch: new_branch.to_string(),
117→            stderr,
118→        });
119→    }
120→
121→    // Step 2: git checkout -b <new_branch> in the cloned directory
122→    let checkout_output = Command::new("git")
123→        .args(["checkout", "-b", new_branch])
124→        .current_dir(target_dir)
125→        .output()
126→        .map_err(|e| CloneError::GitNotFound(e.to_string()))?;
127→
128→    if !checkout_output.status.success() {
129→        let stderr = String::from_utf8_lossy(&checkout_output.stderr).to_string();
130→        return Err(CloneError::GitFailed {
131→            repo: main_workspace_path.to_string_lossy().to_string(),
132→            branch: new_branch.to_string(),
133→            stderr,
134→        });
135→    }
136→
137→    Ok(target_dir.to_path_buf())
138→}
139→
140→/// Build the git clone --local arguments (for testing).
141→pub fn build_local_clone_args(main_workspace_path: &Path, target: &Path) -> Vec<String> {
142→    vec![
143→        "clone".to_string(),
144→        "--local".to_string(),
145→        main_workspace_path.to_string_lossy().to_string(),
146→        target.to_string_lossy().to_string(),
147→    ]
148→}
149→
150→/// Build the git clone command arguments (for testing/debugging without executing).
151→pub fn build_clone_args(url: &str, branch: &str, target: &Path) -> Vec<String> {
152→    let mut args = vec!["clone".to_string()];
153→
154→    if is_local_path(url) {
155→        args.push("--local".to_string());
156→    }
157→
158→    args.push("-b".to_string());
159→    args.push(branch.to_string());
160→    args.push(url.to_string());
161→    args.push(target.to_string_lossy().to_string());
162→
163→    args
164→}
