166→#[derive(Debug, thiserror::Error)]
167→pub enum CloneError {
168→    #[error("git not found: {0}")]
169→    GitNotFound(String),
170→
171→    #[error("git clone failed for {repo}/{branch}: {stderr}")]
172→    GitFailed {
173→        repo: String,
174→        branch: String,
175→        stderr: String,
176→    },
177→
178→    #[error("filesystem error at {path}: {err}", path = .0.display(), err = .1)]
179→    Filesystem(PathBuf, std::io::Error),
180→}
