 10→/// A single item in the flattened display list.
 11→pub struct DisplayItem {
 12→    /// Text to show
 13→    pub display: String,
 14→    /// Workspace status (None = repo header)
 15→    pub status: Option<WorkspaceStatus>,
 16→    /// Workspace id if this is a branch item
 17→    pub workspace_id: Option<String>,
 18→}
 19→
 20→#[derive(Clone, Copy)]
 21→pub enum WorkspaceStatus {
 22→    /// tmux session alive
 23→    Running,
 24→    /// Container stopped, no tmux
 25→    Stopped,
 26→    /// Not cloned yet
 27→    Lazy,
 28→}
 29→
 30→struct RepoGroup {
 31→    name: String,
 32→    workspaces: Vec<WorkspaceItem>,
 33→    expanded: bool,
 34→}
 35→
 36→struct WorkspaceItem {
 37→    branch: String,
 38→    workspace_id: String,
 39→    status: WorkspaceStatus,
 40→}
 41→
 42→pub struct App {
 43→    repos: Vec<RepoGroup>,
 44→    selected: usize,
 45→    item_count: usize,
 46→}
 47→
 48→impl App {
 49→    /// Build app state from workspace state and live backend status.
 50→    pub fn new(state: &WorkspaceState, backend: &dyn MultiplexerBackend) -> Self {
 51→        let workspace_root = state.workspace_root();
 52→
 53→        // Group workspaces by repo (preserve insertion order)
 54→        let mut repo_names: Vec<String> = Vec::new();
 55→        for ws in state.all_workspaces() {
 56→            if !repo_names.contains(&ws.repo) {
 57→                repo_names.push(ws.repo.clone());
 58→            }
 59→        }
 60→
 61→        let repos: Vec<RepoGroup> = repo_names
 62→            .iter()
 63→            .map(|repo| {
 64→                let workspaces = state
 65→                    .workspaces_for_repo(repo)
 66→                    .into_iter()
 67→                    .map(|ws| {
 68→                        let session_name = config::session_name(&ws.repo, &ws.branch);
 69→                        let container_name = config::container_name(&ws.repo, &ws.branch);
 70→                        let clone_exists = if ws.path.is_some() {
 71→                            ws.path
 72→                                .as_ref()
 73→                                .is_some_and(|p| std::path::PathBuf::from(p).join(".git").exists())
 74→                        } else {
 75→                            clone::workspace_exists(&workspace_root, &ws.repo, &ws.branch)
 76→                        };
 77→
 78→                        let status = if backend.is_alive(&session_name) {
 79→                            WorkspaceStatus::Running
 80→                        } else if matches!(
 81→                            container::status(&container_name),
 82→                            container::ContainerStatus::Stopped
 83→                        ) || clone_exists
 84→                        {
 85→                            WorkspaceStatus::Stopped
 86→                        } else {
 87→                            WorkspaceStatus::Lazy
 88→                        };
 89→
 90→                        WorkspaceItem {
 91→                            branch: ws.branch.clone(),
 92→                            workspace_id: config::workspace_id(&ws.repo, &ws.branch),
 93→                            status,
 94→                        }
 95→                    })
 96→                    .collect();
 97→
 98→                RepoGroup {
 99→                    name: repo.clone(),
100→                    workspaces,
101→                    expanded: true,
102→                }
103→            })
104→            .collect();
105→
106→        let item_count = Self::count_items(&repos);
107→        App {
108→            repos,
109→            selected: 0,
110→            item_count,
111→        }
112→    }
113→
114→    fn count_items(repos: &[RepoGroup]) -> usize {
115→        repos
116→            .iter()
117→            .map(|r| 1 + if r.expanded { r.workspaces.len() } else { 0 })
118→            .sum()
119→    }
120→
121→    /// Flatten repos into display items for rendering.
122→    pub fn flatten_items(&self) -> Vec<DisplayItem> {
123→        let mut items = Vec::new();
124→        for repo in &self.repos {
125→            let chevron = if repo.expanded { "▼" } else { "▶" };
126→            items.push(DisplayItem {
127→                display: format!("{chevron} {}", repo.name),
128→                status: None,
129→                workspace_id: None,
130→            });
131→            if repo.expanded {
132→                for ws in &repo.workspaces {
133→                    let icon = match ws.status {
134→                        WorkspaceStatus::Running => "●",
135→                        WorkspaceStatus::Stopped => "○",
136→                        WorkspaceStatus::Lazy => "◌",
137→                    };
138→                    let label = match ws.status {
139→                        WorkspaceStatus::Running => "running",
140→                        WorkspaceStatus::Stopped => "stopped",
141→                        WorkspaceStatus::Lazy => "lazy",
142→                    };
143→                    let branch_display = config::decode_branch(&config::encode_branch(&ws.branch));
144→                    items.push(DisplayItem {
145→                        display: format!("  {branch_display:<24} {icon} {label}"),
146→                        status: Some(ws.status),
147→                        workspace_id: Some(ws.workspace_id.clone()),
148→                    });
149→                }
150→            }
151→        }
152→        items
153→    }
154→
155→    pub fn selected(&self) -> usize {
156→        self.selected
157→    }
158→
159→    pub fn move_down(&mut self) {
160→        if self.selected + 1 < self.item_count {
161→            self.selected += 1;
162→        }
163→    }
164→
165→    pub fn move_up(&mut self) {
166→        self.selected = self.selected.saturating_sub(1);
167→    }
168→
169→    /// Get the workspace_id of the currently selected item, or None if it's a repo header.
170→    pub fn selected_workspace_id(&self) -> Option<String> {
171→        let items = self.flatten_items();
172→        items
173→            .get(self.selected)
174→            .and_then(|item| item.workspace_id.clone())
175→    }
176→
177→    /// Toggle expand/collapse of the repo group at the current selection.
178→    pub fn toggle_expand(&mut self) {
179→        // Find which repo group this index belongs to
180→        let mut idx = 0;
181→        for repo in &mut self.repos {
182→            if idx == self.selected {
183→                repo.expanded = !repo.expanded;
184→                self.item_count = Self::count_items_from_repos(&self.repos);
185→                // Clamp selected if it now exceeds item count
186→                if self.selected >= self.item_count {
187→                    self.selected = self.item_count.saturating_sub(1);
188→                }
189→                return;
190→            }
191→            idx += 1;
192→            if repo.expanded {
193→                idx += repo.workspaces.len();
194→            }
195→        }
196→    }
197→
198→    fn count_items_from_repos(repos: &[RepoGroup]) -> usize {
199→        Self::count_items(repos)
200→    }
201→}
202→
203→/// Main TUI entry point.
204→///
205→/// Returns `Ok(Some(workspace_id))` if user selected a workspace to launch.
206→/// Returns `Ok(None)` if user quit.
207→pub fn run(
208→    state: &WorkspaceState,
209→    backend: &dyn MultiplexerBackend,
210→) -> Result<Option<String>, Box<dyn std::error::Error>> {
211→    let mut terminal = ratatui::init();
212→    let mut app = App::new(state, backend);
213→
214→    let result = loop {
215→        terminal.draw(|frame| ui::render(frame, &app))?;
216→
217→        if let Some(action) = event::handle_events(&mut app)? {
218→            match action {
219→                event::Action::Quit => break Ok(None),
220→                event::Action::Select(workspace_id) => {
221→                    break Ok(Some(workspace_id));
222→                }
223→            }
224→        }
225→    };
226→
227→    ratatui::restore();
228→    result
229→}
