  1→use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind};
  2→
  3→use super::app::App;
  4→
  5→pub enum Action {
  6→    Quit,
  7→    Select(String), // workspace_id
  8→}
  9→
 10→pub fn handle_events(app: &mut App) -> Result<Option<Action>, Box<dyn std::error::Error>> {
 11→    if event::poll(std::time::Duration::from_millis(100))?
 12→        && let Event::Key(key) = event::read()?
 13→        && key.kind == KeyEventKind::Press
 14→    {
 15→        return Ok(handle_key(app, key));
 16→    }
 17→    Ok(None)
 18→}
 19→
 20→fn handle_key(app: &mut App, key: KeyEvent) -> Option<Action> {
 21→    match key.code {
 22→        KeyCode::Char('q') | KeyCode::Esc => Some(Action::Quit),
 23→        KeyCode::Up | KeyCode::Char('k') => {
 24→            app.move_up();
 25→            None
 26→        }
 27→        KeyCode::Down | KeyCode::Char('j') => {
 28→            app.move_down();
 29→            None
 30→        }
 31→        KeyCode::Enter => {
 32→            if let Some(workspace_id) = app.selected_workspace_id() {
 33→                Some(Action::Select(workspace_id))
 34→            } else {
 35→                // Selected a repo header — toggle expand/collapse
 36→                app.toggle_expand();
 37→                None
 38→            }
 39→        }
 40→        _ => None,
 41→    }
 42→}
