206→/// Write a default .dual/settings.json with Dual-specific fields only.
207→/// Container config belongs in devcontainer.json.
208→/// Creates the .dual/ directory if it doesn't exist.
209→pub fn write_default_dual_config(
210→    repo_root: &Path,
211→    devcontainer_path: &str,
212→) -> Result<(), HintsError> {
213→    let dual_dir = repo_root.join(DUAL_DIR);
214→    std::fs::create_dir_all(&dual_dir).map_err(|e| HintsError::WriteError(dual_dir.clone(), e))?;
215→
216→    let config = DualConfig {
217→        devcontainer: devcontainer_path.to_string(),
218→        ..Default::default()
219→    };
220→
221→    let path = dual_dir.join(SETTINGS_FILENAME);
222→    let contents = serde_json::to_string_pretty(&config).map_err(HintsError::JsonSerializeError)?;
223→    std::fs::write(&path, contents).map_err(|e| HintsError::WriteError(path, e))?;
224→    Ok(())
225→}
