 148→        Err(e) => {
 149→            error!("{e}");
 150→            return 1;
 151→        }
 152→    };
 153→
 154→    // Check for duplicates
 155→    if st.has_workspace(&repo_name, &branch) {
 156→        error!("workspace {}/{} already exists", repo_name, branch);
 157→        return 1;
 158→    }
 159→
 160→    // Determine devcontainer.json path (detect existing or create default)
 161→    let devcontainer_path = if let Some(dc) = dual::devcontainer::find_devcontainer_json(&repo_root)
 162→    {
 163→        dc.strip_prefix(&repo_root)
 164→            .unwrap_or(&dc)
 165→            .to_string_lossy()
 166→            .to_string()
 167→    } else {
 168→        if let Err(e) = config::write_default_devcontainer(&repo_root) {
 169→            warn!("failed to write devcontainer.json: {e}");
 170→        } else {
 171→            info!("Created .devcontainer/devcontainer.json (image: node:20)");
 172→            info!("Edit it to customize image, ports, setup command, and env vars.");
 173→        }
 174→        ".devcontainer/devcontainer.json".to_string()
 175→    };
 176→
 177→    // Create .dual/settings.json if missing
 178→    let settings_path = repo_root.join(".dual").join("settings.json");
 179→    if !settings_path.exists() {
 180→        if let Err(e) = config::write_default_dual_config(&repo_root, &devcontainer_path) {
 181→            warn!("failed to write .dual/settings.json: {e}");
 182→        } else {
 183→            info!("Created .dual/settings.json (Dual orchestration settings)");
 184→        }
 185→    }
 186→
 187→    // Initialize shared directory if shared files are configured
 188→    let hints = config::load_hints(&repo_root).unwrap_or_default();
 189→    if !hints.shared.is_empty() {
 190→        match shared::ensure_shared_dir(&repo_name) {
 191→            Ok(shared_dir) => {
 192→                match shared::init_from_main(&repo_root, &shared_dir, &hints.shared) {
 193→                    Ok(moved) => {
 194→                        for f in &moved {
 195→                            info!("  shared: {f} → ~/.dual/shared/{repo_name}/");
 196→                        }
 197→                    }
 198→                    Err(e) => warn!("shared init failed: {e}"),
 199→                }
 200→            }
 201→            Err(e) => warn!("could not create shared directory: {e}"),
 202→        }
 203→    }
 204→
 205→    // Add workspace entry
 206→    let entry = state::WorkspaceEntry {
 207→        repo: repo_name.clone(),
 208→        url,
 209→        branch: branch.clone(),
 210→        path: Some(repo_root.to_string_lossy().to_string()),
 211→    };
 212→
 213→    if let Err(e) = st.add_workspace(entry) {
 214→        error!("{e}");
 215→        return 1;
 216→    }
 217→
 218→    // Save state
 219→    if let Err(e) = state::save(&st) {
 220→        error!("failed to save state: {e}");
 221→        return 1;
 222→    }
 223→
 224→    let ws_id = config::workspace_id(&repo_name, &branch);
 225→    info!("Initialized workspace: {ws_id}");
 226→    info!("Use `dual launch {ws_id}` to start.");
 227→    0
 228→}
