 230→/// Create a new branch workspace for an existing repo.
 231→fn cmd_create(repo_arg: Option<&str>, branch: &str) -> i32 {
 232→    let mut st = match state::load() {
 233→        Ok(s) => s,
 234→        Err(e) => {
 235→            error!("{e}");
 236→            return 1;
 237→        }
 238→    };
 239→
 240→    // Resolve repo name: use --repo if provided, otherwise auto-detect from cwd
 241→    let repo = match repo_arg {
 242→        Some(r) => r.to_string(),
 243→        None => match detect_repo_from_cwd(&st) {
 244→            Some(r) => {
 245→                info!("Auto-detected repo: {r}");
 246→                r
 247→            }
 248→            None => {
 249→                error!("could not detect repo from current directory");
 250→                info!("Usage: dual create <branch> --repo <name>");
 251→                info!("Or run from inside a repo that was initialized with `dual init`.");
 252→                return 1;
 253→            }
 254→        },
 255→    };
 256→
 257→    // Find an existing workspace for this repo
 258→    let existing = st.workspaces_for_repo(&repo);
 259→    if existing.is_empty() {
 260→        error!("repo '{repo}' not found. Run `dual init` inside the repo first.");
 261→        return 1;
 262→    }
 263→
 264→    // Check if this branch already exists
 265→    if st.has_workspace(&repo, branch) {
 266→        error!("workspace {repo}/{branch} already exists");
 267→        return 1;
 268→    }
 269→
 270→    // Get URL from existing entry
 271→    let url = existing[0].url.clone();
 272→
 273→    // Add new entry (no explicit path — will be cloned on launch)
 274→    let entry = state::WorkspaceEntry {
 275→        repo: repo.clone(),
 276→        url,
 277→        branch: branch.to_string(),
 278→        path: None,
 279→    };
 280→
 281→    if let Err(e) = st.add_workspace(entry) {
 282→        error!("{e}");
 283→        return 1;
 284→    }
 285→
 286→    if let Err(e) = state::save(&st) {
 287→        error!("failed to save state: {e}");
 288→        return 1;
 289→    }
 290→
 291→    let ws_id = config::workspace_id(&repo, branch);
 292→    info!("Created workspace: {ws_id}");
 293→    info!("Use `dual launch {ws_id}` to start.");
 294→    0
 295→}
