 539→/// Destroy a workspace: tmux → container → clone.
 540→fn cmd_destroy(workspace_arg: Option<&str>, backend: &dyn MultiplexerBackend) -> i32 {
 541→    let mut st = match state::load() {
 542→        Ok(s) => s,
 543→        Err(e) => {
 544→            error!("{e}");
 545→            return 1;
 546→        }
 547→    };
 548→
 549→    // Resolve workspace: use arg if provided, otherwise auto-detect from cwd
 550→    let workspace;
 551→    let entry = if let Some(ws) = workspace_arg {
 552→        workspace = ws.to_string();
 553→        match st.resolve_workspace(ws) {
 554→            Some(e) => e.clone(),
 555→            None => {
 556→                error!("unknown workspace '{ws}'");
 557→                return 1;
 558→            }
 559→        }
 560→    } else {
 561→        match detect_workspace(&st) {
 562→            Some(e) => {
 563→                workspace = config::workspace_id(&e.repo, &e.branch);
 564→                info!("Auto-detected workspace: {workspace}");
 565→                e
 566→            }
 567→            None => {
 568→                error!("could not detect workspace from current directory");
 569→                info!("Usage: dual destroy [workspace]");
 570→                return 1;
 571→            }
 572→        }
 573→    };
 574→
 575→    let workspace_root = st.workspace_root();
 576→    let container_name = config::container_name(&entry.repo, &entry.branch);
 577→    let session_name = config::session_name(&entry.repo, &entry.branch);
 578→
 579→    // Destroy tmux session
 580→    if backend.is_alive(&session_name) {
 581→        info!("Destroying session {session_name}...");
 582→        if let Err(e) = backend.destroy(&session_name) {
 583→            warn!("session destroy failed: {e}");
 584→        }
 585→    }
 586→
 587→    // Stop and remove container
 588→    match container::status(&container_name) {
 589→        container::ContainerStatus::Running => {
 590→            info!("Stopping container {container_name}...");
 591→            if let Err(e) = container::stop(&container_name) {
 592→                warn!("container stop failed: {e}");
 593→            }
 594→            info!("Removing container {container_name}...");
 595→            if let Err(e) = container::destroy(&container_name) {
 596→                warn!("container remove failed: {e}");
 597→            }
 598→        }
 599→        container::ContainerStatus::Stopped => {
 600→            info!("Removing container {container_name}...");
 601→            if let Err(e) = container::destroy(&container_name) {
 602→                warn!("container remove failed: {e}");
 603→            }
 604→        }
 605→        container::ContainerStatus::Missing => {}
 606→    }
 607→
 608→    // Remove clone (only for non-explicit-path workspaces)
 609→    if entry.path.is_none() && clone::workspace_exists(&workspace_root, &entry.repo, &entry.branch)
 610→    {
 611→        info!("Removing clone...");
 612→        if let Err(e) = clone::remove_workspace(&workspace_root, &entry.repo, &entry.branch) {
 613→            error!("failed to remove clone: {e}");
 614→            return 1;
 615→        }
 616→    }
 617→
 618→    // Remove from state
 619→    st.remove_workspace(&entry.repo, &entry.branch);
 620→    if let Err(e) = state::save(&st) {
 621→        warn!("failed to save state: {e}");
 622→    }
 623→
 624→    info!("Workspace '{workspace}' destroyed.");
 625→    0
 626→}
