 628→/// Open workspace services in the default browser.
 629→fn cmd_open(workspace: Option<String>) -> i32 {
 630→    let st = match state::load() {
 631→        Ok(s) => s,
 632→        Err(e) => {
 633→            error!("{e}");
 634→            return 1;
 635→        }
 636→    };
 637→
 638→    let url_groups = proxy::workspace_urls(&st);
 639→    if url_groups.is_empty() {
 640→        info!("No URLs configured. Add 'forwardPorts' to devcontainer.json in your repo.");
 641→        return 0;
 642→    }
 643→
 644→    // Filter by workspace if specified
 645→    let filtered: Vec<_> = match &workspace {
 646→        Some(ws) => url_groups.into_iter().filter(|(id, _)| id == ws).collect(),
 647→        None => url_groups,
 648→    };
 649→
 650→    if filtered.is_empty() {
 651→        if let Some(ws) = &workspace {
 652→            error!("no URLs for workspace '{ws}'");
 653→        }
 654→        return 1;
 655→    }
 656→
 657→    for (_, urls) in &filtered {
 658→        for url_line in urls {
 659→            // Extract the URL part (after the status icon)
 660→            let url = url_line
 661→                .trim()
 662→                .trim_start_matches('\u{25cf}')
 663→                .trim_start_matches('\u{25cb}')
 664→                .trim();
 665→            let http_url = format!("http://{url}");
 666→            #[cfg(target_os = "macos")]
 667→            let _ = std::process::Command::new("open").arg(&http_url).spawn();
 668→            #[cfg(target_os = "linux")]
 669→            let _ = std::process::Command::new("xdg-open")
 670→                .arg(&http_url)
 671→                .spawn();
 672→            info!("Opening {http_url}");
 673→        }
 674→    }
 675→
 676→    0
 677→}
