 738→/// Sync shared config files for a workspace.
 739→fn cmd_sync(workspace_arg: Option<String>) -> i32 {
 740→    let st = match state::load() {
 741→        Ok(s) => s,
 742→        Err(e) => {
 743→            error!("{e}");
 744→            return 1;
 745→        }
 746→    };
 747→
 748→    // Resolve which workspace we're syncing
 749→    let entry = if let Some(ws) = workspace_arg {
 750→        match st.resolve_workspace(&ws) {
 751→            Some(e) => e.clone(),
 752→            None => {
 753→                error!("unknown workspace '{ws}'");
 754→                return 1;
 755→            }
 756→        }
 757→    } else {
 758→        match detect_workspace(&st) {
 759→            Some(e) => e,
 760→            None => {
 761→                error!("not inside a dual workspace");
 762→                info!("Usage: dual sync [workspace]");
 763→                return 1;
 764→            }
 765→        }
 766→    };
 767→
 768→    // Load hints
 769→    let workspace_dir = st.workspace_dir(&entry);
 770→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
 771→    if hints.shared.is_empty() {
 772→        error!("no shared files configured in .dual/settings.json");
 773→        return 1;
 774→    }
 775→
 776→    let shared_dir = match shared::ensure_shared_dir(&entry.repo) {
 777→        Ok(d) => d,
 778→        Err(e) => {
 779→            error!("{e}");
 780→            return 1;
 781→        }
 782→    };
 783→
 784→    let is_main = entry.path.is_some();
 785→
 786→    if is_main {
 787→        // Main workspace: init shared dir, then prompt to sync all branches
 788→        match shared::init_from_main(&workspace_dir, &shared_dir, &hints.shared) {
 789→            Ok(moved) => {
 790→                for f in &moved {
 791→                    info!("  moved {f} → shared/");
 792→                }
 793→            }
 794→            Err(e) => {
 795→                error!("{e}");
 796→                return 1;
 797→            }
 798→        }
 799→
 800→        // Prompt to sync all branches
 801→        let branches: Vec<_> = st
 802→            .workspaces_for_repo(&entry.repo)
 803→            .into_iter()
 804→            .filter(|ws| ws.path.is_none())
 805→            .collect();
 806→
 807→        if branches.is_empty() {
 808→            info!("No branch workspaces to sync.");
 809→            return 0;
 810→        }
 811→
 812→        // Interactive prompt — use println! directly since this is user interaction
 813→        println!(
 814→            "\nSync shared files to ALL {} branch workspace(s)? [y/N]",
 815→            branches.len()
 816→        );
 817→        let mut input = String::new();
 818→        std::io::stdin().read_line(&mut input).unwrap_or(0);
 819→        if !input.trim().eq_ignore_ascii_case("y") {
 820→            info!("Cancelled.");
 821→            return 0;
 822→        }
 823→
 824→        for branch_entry in &branches {
 825→            let branch_dir = st.workspace_dir(branch_entry);
 826→            if !branch_dir.exists() {
 827→                continue; // Not yet cloned
 828→            }
 829→            let ws_id = config::workspace_id(&branch_entry.repo, &branch_entry.branch);
 830→            match shared::copy_to_branch(&branch_dir, &shared_dir, &hints.shared) {
 831→                Ok(copied) => {
 832→                    info!("{ws_id}: synced {} file(s)", copied.len());
 833→                }
 834→                Err(e) => error!("{ws_id}: {e}"),
 835→            }
 836→        }
 837→    } else {
 838→        // Branch workspace: copy from shared dir
 839→        match shared::copy_to_branch(&workspace_dir, &shared_dir, &hints.shared) {
 840→            Ok(copied) => {
 841→                if copied.is_empty() {
 842→                    info!(
 843→                        "No shared files available yet. Run `dual sync` in the main workspace first."
 844→                    );
 845→                } else {
 846→                    for f in &copied {
 847→                        info!("  synced {f}");
 848→                    }
 849→                }
 850→            }
 851→            Err(e) => {
 852→                error!("{e}");
 853→                return 1;
 854→            }
 855→        }
 856→    }
 857→
 858→    0
 859→}
