 915→/// Print workspace status grouped by repo.
 916→fn print_workspace_status(st: &state::WorkspaceState, backend: &dyn MultiplexerBackend) {
 917→    let workspace_root = st.workspace_root();
 918→
 919→    // Collect unique repo names in order of first appearance
 920→    let mut repos: Vec<String> = Vec::new();
 921→    for ws in st.all_workspaces() {
 922→        if !repos.contains(&ws.repo) {
 923→            repos.push(ws.repo.clone());
 924→        }
 925→    }
 926→
 927→    for repo in &repos {
 928→        println!("{repo}");
 929→        for ws in st.workspaces_for_repo(repo) {
 930→            let container_name = config::container_name(&ws.repo, &ws.branch);
 931→            let session_name = config::session_name(&ws.repo, &ws.branch);
 932→
 933→            let clone_exists = if ws.path.is_some() {
 934→                ws.path
 935→                    .as_ref()
 936→                    .map(|p| PathBuf::from(p).join(".git").exists())
 937→                    .unwrap_or(false)
 938→            } else {
 939→                clone::workspace_exists(&workspace_root, &ws.repo, &ws.branch)
 940→            };
 941→            let container_st = container::status(&container_name);
 942→            let tmux_alive = backend.is_alive(&session_name);
 943→
 944→            let (icon, status_text) = match (&container_st, tmux_alive) {
 945→                (container::ContainerStatus::Running, true) => {
 946→                    ("\u{25cf}", "running  (container: up, tmux: attached)")
 947→                }
 948→                (container::ContainerStatus::Running, false) => {
 949→                    ("\u{25cf}", "running  (container: up, tmux: none)")
 950→                }
 951→                (container::ContainerStatus::Stopped, true) => (
 952→                    "\u{25cb}",
 953→                    "stopped  (container: stopped, tmux: background)",
 954→                ),
 955→                (container::ContainerStatus::Stopped, false) => {
 956→                    ("\u{25cb}", "stopped  (container: stopped, tmux: none)")
 957→                }
 958→                (container::ContainerStatus::Missing, _) if clone_exists => {
 959→                    ("\u{25cb}", "stopped  (not launched)")
 960→                }
 961→                (container::ContainerStatus::Missing, _) => {
 962→                    ("\u{25cc}", "lazy     (not cloned yet)")
 963→                }
 964→            };
 965→
 966→            let branch_display = config::decode_branch(&config::encode_branch(&ws.branch));
 967→            println!("  {branch_display:<24} {icon} {status_text}");
 968→        }
 969→        println!();
 970→    }
 971→}
