 973→/// Detect git repo info from the current directory.
 974→fn detect_git_repo() -> Result<(PathBuf, String, String), String> {
 975→    // Get repo root
 976→    let root_output = std::process::Command::new("git")
 977→        .args(["rev-parse", "--show-toplevel"])
 978→        .output()
 979→        .map_err(|_| "git not found".to_string())?;
 980→    if !root_output.status.success() {
 981→        return Err("not inside a git repository".to_string());
 982→    }
 983→    let root = PathBuf::from(String::from_utf8_lossy(&root_output.stdout).trim());
 984→
 985→    // Get remote URL
 986→    let url_output = std::process::Command::new("git")
 987→        .args(["remote", "get-url", "origin"])
 988→        .output()
 989→        .map_err(|_| "git not found".to_string())?;
 990→    let url = if url_output.status.success() {
 991→        String::from_utf8_lossy(&url_output.stdout)
 992→            .trim()
 993→            .to_string()
 994→    } else {
 995→        root.to_string_lossy().to_string() // local-only repo, use path as URL
 996→    };
 997→
 998→    // Get current branch
 999→    let branch_output = std::process::Command::new("git")
1000→        .args(["rev-parse", "--abbrev-ref", "HEAD"])
1001→        .output()
1002→        .map_err(|_| "git not found".to_string())?;
1003→    let branch = String::from_utf8_lossy(&branch_output.stdout)
1004→        .trim()
1005→        .to_string();
1006→
1007→    Ok((root, url, branch))
1008→}
