1010→/// Derive a short repo name from a directory path.
1011→/// "/Users/jeevan/code/lightfast" → "lightfast"
1012→fn derive_repo_name(path: &std::path::Path) -> String {
1013→    path.file_name()
1014→        .and_then(|n| n.to_str())
1015→        .unwrap_or("repo")
1016→        .to_string()
1017→}
