            .to_string();
        return InitResult {
            devcontainer_path: rel_path,
            create_devcontainer: false,
            image: String::new(),
            ports: Vec::new(),
            setup: None,
        };
    }

    InitResult {
        devcontainer_path: ".devcontainer/devcontainer.json".to_string(),
        create_devcontainer: true,
        image: "node:20".to_string(),
        ports: Vec::new(),
        setup: None,
