    let dc_path = dc_dir.join("devcontainer.json");
    let content = r#"{
    "image": "node:20"
}
"#;
    std::fs::write(&dc_path, content).map_err(|e| HintsError::WriteError(dc_path, e))?;
    Ok(())
}

